eventScripts.script:
try : 
	path = tagPath

	config = system.tag.getConfiguration(path, False)
	name = config[0]['name']

	params = {'tagName':name,'tagValue':currentValue.value,'PrevValue':previousValue.value,'changeTime':currentValue.timestamp}

	system.db.runNamedQuery("BACC_PunchSleavingAndNGP", "TagUpdates/QueryWriteTagValue", params)
except : 
	pass

if (currentValue >= 1431 and currentValue <= 1435) or currentValue == 1260 and currentValue == 1905 :
	data = system.tag.readBlocking("[default]BACC_PunchSleevingNGP/NGP1/Station/Faults/ConsecutiveFaults/Fault_{id}".format(id = currentValue))
	lastValue = data[0].value
	newValue = lastValue + 1
	system.tag.writeBlocking("[default]BACC_PunchSleevingNGP/NGP1/Station/Faults/ConsecutiveFaults/Fault_{id}".format(id = currentValue), newValue)
